// Calendar visual baselines (#66): every viewport × theme project (360/768/1280, light and dark).
// Baselines are only generated by the e2e workflow's `update_snapshots` dispatch; without one the
// test is skipped (see e2e/README.md).
import { existsSync } from 'node:fs';

import { COURTS_WORKSPACE } from '../../fixtures/courts-data.ts';
import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

for (const view of ['week', 'month']) {
  test(`calendar ${view}`, async ({ page, asUser }, testInfo) => {
    const name = `calendar-${view}.png`;
    test.skip(
      testInfo.config.updateSnapshots === 'none' &&
        !existsSync(testInfo.snapshotPath(name, { kind: 'screenshot' })),
      'no baseline yet: dispatch the e2e workflow with update_snapshots',
    );
    await asUser('owner', {
      workspace: COURTS_WORKSPACE,
      path: `calendar?view=${view}&day=2026-11-04`,
    });
    await shellReady(page);
    await expect(page.locator('main')).toHaveScreenshot(name);
  });
}
